using System;
using System.Collections.Generic;
using System.Text;
using CumbriaCQ.Offline;
class C4fmProfileTests {
 static int checks;
 static void Check(bool ok,string message){checks++;if(!ok)throw new Exception(message);}
 static VoiceEngine Engine(){return new VoiceEngine("TESTGW/WX",50,"D1C000B00000TEST10","B0 0    0000000",false);}
 static string Header(int mode,string caller,byte[] data){string[] prefixes={"D1F005220016000","D1F005221016000","D1F006C20016000","D1F006C21016000"};byte[] tail=new byte[mode<2?7:20];if(data!=null)Array.Copy(data,tail,Math.Min(data.Length,tail.Length));return prefixes[mode]+"*****R0001"+caller.PadRight(10)+new string(' ',40)+BitConverter.ToString(tail).Replace("-","");}
 static int[] Info(byte[] p){byte[] b=new byte[25];Array.Copy(p,40,b,0,25);return YsfWire.ReadFich(b);}
 static readonly byte[] White={0x93,0xD7,0x51,0x21,0x9C,0x2F,0x6C,0xD0,0xEF,0x0F,0xF8,0x3D,0xF1,0x73,0x20,0x94,0xED,0x1E,0x7C,0xD8};
 static int Bit(byte[] b,int i){return (b[i/8]>>(7-i%8))&1;}
 static byte[] Decode(byte[] p,int size,int offset){int chunk=size==10?5:9,steps=size==10?100:180,columns=size==10?5:9;byte[] enc=new byte[chunk*5];for(int i=0;i<5;i++)Array.Copy(p,offset+i*18,enc,i*chunk,chunk);byte[] raw=new byte[size+3];int d1=0,d2=0,d3=0,d4=0;for(int i=0;i<steps;i++){int n=i/columns*2+i%columns*40;int d=Bit(enc,n)^d3^d4;Check(Bit(enc,n+1)==(d^d1^d2^d4),"DCH FEC");if(d!=0)raw[i/8]|=(byte)(128>>(i%8));d4=d3;d3=d2;d2=d1;d1=d;}int crc=0;for(int i=0;i<size;i++){crc^=raw[i]<<8;for(int b=0;b<8;b++)crc=((crc<<1)^((crc&32768)!=0?0x1021:0))&65535;}crc=(~crc)&65535;Check(raw[size]==(byte)(crc>>8)&&raw[size+1]==(byte)crc,"DCH CRC");for(int i=0;i<size;i++)raw[i]^=White[i];Array.Resize(ref raw,size);return raw;}
 static byte[] Record(int length,int first){byte[] d=new byte[length];d[0]=(byte)first;d[1]=0x22;d[2]=(byte)(length==7?0x61:0x62);d[3]=0x5F;d[4]=0xD5;if(length==20){d[8]=0;d[9]=0xE9;}d[length-2]=3;int sum=0;for(int i=0;i<length-1;i++)sum+=d[i];d[length-1]=(byte)sum;return d;}
 static void Auxiliary(){for(int mode=0;mode<4;mode++){foreach(int first in new[]{1,7}){byte[] record=Record(7,first);var e=Engine();e.OnClient(Header(mode,"TESTCALL",record),0);VerifyAux(Stream(e,21),record,6);}if(mode>=2){byte[] record=Record(20,0x31);var e=Engine();e.OnClient(Header(mode,"TESTCALL",record),0);VerifyAux(Stream(e,24),record,7);}}}
 static void VerifyAux(List<byte[]> packets,byte[] record,int total){int voice=0,blocks=0;foreach(byte[] p in packets){int[] f=Info(p);Check(f[2]==total,"Record length must select FT"+total);if(f[0]!=1)continue;Check(f[1]==voice%(total+1),"FN rollover disagrees with FT");byte[] expected=new byte[65];for(int n=0;n<65;n++)expected[n]=(byte)(voice*17+n);Check(BitConverter.ToString(VoiceCodec.GetVoice(p))==BitConverter.ToString(expected),"Auxiliary path changed voice");if(f[1]>=6){byte[] actual=Decode(p,10,65);for(int n=0;n<10;n++){int at=(f[1]-6)*10+n;Check(actual[n]==(at<record.Length?record[at]:0),"Binary data or short-record padding changed");}blocks++;}voice++;}Check(blocks>=3,"Complete auxiliary cycles absent");}
 static List<byte[]> Stream(VoiceEngine e,int count){var packets=new List<byte[]>();for(int i=0;i<count;i++){byte[] voice=new byte[65];for(int n=0;n<65;n++)voice[n]=(byte)(i*17+n);packets.AddRange(e.OnClient(VoiceCodec.SerialVoice("D1E",i*5,voice),i*100).Network);packets.AddRange(e.Tick(i*100).Network);}e.OnClient("P010000",count*100);packets.AddRange(e.Tick(count*100).Network);return packets;}
 static void NoData(){for(int mode=0;mode<4;mode++){var e=Engine();Check(e.OnClient(Header(mode,"TESTCALL",null),0).Serial.Contains("D1F00010"),"Recognised metadata lost ACK");int voices=0,headers=0;foreach(byte[] p in Stream(e,18)){int[] f=Info(p);Check(f[2]==5,"No-data transmission must declare FT5, not phantom DT1/DT2");if(f[0]==1){Check(f[1]==voices%6,"No-data cycle must roll FN0..5");byte[] expected=new byte[65];for(int n=0;n<65;n++)expected[n]=(byte)(voices*17+n);Check(BitConverter.ToString(VoiceCodec.GetVoice(p))==BitConverter.ToString(expected),"Voice changed");voices++;}else headers++;}Check(voices==18&&headers==2,"Incomplete over");}}
 static string WithFields(string header){return header.Substring(0,35)+"NATIVEGW  "+"UPLINK    "+"A1111B2222C3333D4444"+header.Substring(75);}
 static void IdentityBlocks(){for(int mode=0;mode<4;mode++){var e=Engine();e.OnClient(WithFields(Header(mode,"TESTCALL",null)),0);foreach(byte[] p in Stream(e,18)){int[] f=Info(p);if(f[0]!=1){Check(Encoding.ASCII.GetString(Decode(p,20,74))=="TESTGW/WX UPLINK    ","Header must retain genuine uplink and consistent bridge downlink");Check(Encoding.ASCII.GetString(Decode(p,20,65))=="**********TESTCALL  ","Header source/destination role changed");}else{string[] expected={"**********","TESTCALL  ","TESTGW/WX ","UPLINK    ","A1111B2222","C3333D4444"};Check(Encoding.ASCII.GetString(Decode(p,10,65))==expected[f[1]],"Native CSD identity block discarded at FN"+f[1]);}}}}
 static void InvalidOptional(){for(int mode=0;mode<4;mode++){for(int kind=0;kind<4;kind++){byte[] data=Record(7,1);if(kind==0)data[6]^=1;if(kind==1)data[5]=4;if(kind==2)data[2]=0x60;if(kind==3){Array.Resize(ref data,20);data[14]=1;if(mode<2)continue;}var e=Engine();Check(e.OnClient(Header(mode,"TESTCALL",data),0).Serial.Contains("D1F00010"),"Bad optional data changed metadata ACK");foreach(byte[] p in Stream(e,12))Check(Info(p)[2]==5,"Invalid optional data fabricated a data profile");}}Check(TransmitMetadata.ProfileForFrame(null)==null,"Null metadata accepted");Check(TransmitMetadata.ProfileForFrame(Header(0,"_INVALID",null))==null,"Invalid source profile accepted");}
 static void Boundaries(){var e=Engine();e.OnClient(WithFields(Header(3,"TESTCALL",Record(7,1))),0);var packets=new List<byte[]>();for(int i=0;i<21;i++){if(i==4)e.OnClient(Header(3,"OTHERTEST",Record(20,0x31)),350);byte[] v=new byte[65];for(int n=0;n<65;n++)v[n]=(byte)(i*17+n);packets.AddRange(e.OnClient(VoiceCodec.SerialVoice("D1E",i*5,v),i*100).Network);packets.AddRange(e.Tick(i*100).Network);}packets.AddRange(e.Stop(2100).Network);VerifyAux(packets,Record(7,1),6);foreach(byte[] p in packets){Check(Encoding.ASCII.GetString(p,14,10)=="TESTCALL  ","Caller changed mid-over");int[] f=Info(p);if(f[0]!=1)Check(Encoding.ASCII.GetString(Decode(p,20,74))=="TESTGW/WX UPLINK    ","Terminator used another source profile");}
  Check(e.OnClient(VoiceCodec.SerialVoice("D1E",0,new byte[65]),2200).Network.Count==0,"Stopped metadata revived without header");e.OnClient(Header(0,"OTHERTEST",null),2300);var next=e.OnClient(VoiceCodec.SerialVoice("D1E",0,new byte[65]),2300);next.Network.AddRange(e.Tick(2300).Network);Check(next.Network.Count==2,"New over did not start");foreach(byte[] p in next.Network)Check(Info(p)[2]==5,"Auxiliary profile leaked across Stop");e.SetConnectedRoom("12345",2400);Check(e.OnClient(VoiceCodec.SerialVoice("D1E",5,new byte[65]),2500).Network.Count==0,"Room reset kept metadata");
  var immutable=TransmitMetadata.ProfileForFrame(Header(0,"TESTCALL",Record(7,1)));byte[] block=immutable.DataBlock(6);block[0]^=255;Check(immutable.DataBlock(6)[0]==1,"Returned data mutated profile");bool rejected=false;try{immutable.DataBlock(7);}catch(ArgumentException){rejected=true;}Check(rejected,"FT6 exposed a phantom DT2 block");}
 static int Main(){try{NoData();Auxiliary();IdentityBlocks();InvalidOptional();Boundaries();Console.WriteLine("C4FM_PROFILE_PASS checks="+checks);return 0;}catch(Exception e){Console.WriteLine("C4FM_PROFILE_FAIL "+e.Message);return 1;}}
}
